-- Tool estate catalog: typed aliases + reproducible source-controlled seed.
ALTER TABLE public.tool_aliases
  ADD COLUMN IF NOT EXISTS alias_kind text NOT NULL DEFAULT 'other';

ALTER TABLE public.tool_aliases DROP CONSTRAINT IF EXISTS tool_aliases_alias_kind_check;
ALTER TABLE public.tool_aliases ADD CONSTRAINT tool_aliases_alias_kind_check
  CHECK (alias_kind = ANY (ARRAY['included_service','duplicate_registration','adapter_alias','client_alias','other']));

