REVOKE ALL ON FUNCTION public.seed_tool_estate_for_tenant(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.seed_tool_estate_for_tenant(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seed_tool_estate_for_tenant(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.seed_tool_estate_on_tenant_insert()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $trg$
BEGIN
  PERFORM public.seed_tool_estate_for_tenant(NEW.id);
  RETURN NEW;
END $trg$;

DROP TRIGGER IF EXISTS seed_tool_estate_after_tenant_insert ON public.tenants;
CREATE TRIGGER seed_tool_estate_after_tenant_insert
AFTER INSERT ON public.tenants
FOR EACH ROW EXECUTE FUNCTION public.seed_tool_estate_on_tenant_insert();

-- Reconcile every existing tenant with the source-controlled catalog.
DO $run$
DECLARE t uuid;
BEGIN
  FOR t IN SELECT id FROM public.tenants LOOP
    PERFORM public.seed_tool_estate_for_tenant(t);
  END LOOP;
END $run$;

-- Truthful live proof: the vault metadata index was reached and enumerated safely.
UPDATE public.tool_systems
   SET verification_state = 'live_proven'
 WHERE stable_key = 'sys.marketing_yolo_vault';